def _panel_fit(u, v, design, bounds):
    from scipy.optimize import minimize_scalar

    def loss(a):
        d = design(u, a)
        return np.sum((d @ np.linalg.lstsq(d, v, rcond=None)[0] - v) ** 2)
    a = minimize_scalar(loss, bounds=bounds, method='bounded').x
    d = design(u, a)
    return (a, np.linalg.lstsq(d, v, rcond=None)[0])

def _coordinates(s, x):
    (a, c) = (s['panel_a'], s['panel_c'])
    (u, v) = (a['u'], a['v'])
    (i, j) = np.triu_indices(len(u), 1)
    (off, gain) = ([], [])
    for (p, q) in zip(u.T, v.T):
        delta = p[j] - p[i]
        ok = np.abs(delta) > 1e-10
        slope = np.median((q[j][ok] - q[i][ok]) / delta[ok]) if np.any(ok) else 1.0
        coef = np.array([np.median(q - slope * p), slope])
        d = _affine(p[:, None])
        for _ in range(4):
            r = np.abs(q - d @ coef)
            keep = r <= max(1e-08, 6 * np.median(r))
            if keep.sum() < 2:
                break
            coef = np.linalg.lstsq(d[keep], q[keep], rcond=None)[0]
        off.append(coef[0])
        gain.append(coef[1] if abs(coef[1]) > 1e-06 else 1.0)
    cx = (x - off) / gain

    def atan(q, a):
        return _affine(np.arctan(a * q))

    def rat(q, a):
        return _affine(np.column_stack((q, q * q / (1 + a * q * q))))
    (a1, b1) = _panel_fit(c['u'], c['v1'], atan, (0.5, 4.0))
    (a2, b2) = _panel_fit(c['u'], c['v2'], rat, (0.001, 1.0))
    return np.column_stack((cx, atan(cx, a1) @ b1, rat(cx, a2) @ b2))

def _basis(x):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, j], axis=1) for d in (1, 2, 3) for j in combinations_with_replacement(range(x.shape[1]), d)])
